import{_ as s,o as a,c as i,a2 as t}from"./chunks/framework.BEUshCVJ.js";const k=JSON.parse('{"title":"安装 MeetCue","description":"","frontmatter":{},"headers":[],"relativePath":"zh/install.md","filePath":"zh/install.md","lastUpdated":1792714088000}'),l={name:"zh/install.md"};function o(n,e,p,h,c,d){return a(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="安装-meetcue" tabindex="-1">安装 MeetCue <a class="header-anchor" href="#安装-meetcue" aria-label="Permalink to &quot;安装 MeetCue&quot;">​</a></h1><p>本页介绍如何在 Windows 上安装、升级和卸载 MeetCue。全程不需要管理员权限。</p><h2 id="系统要求" tabindex="-1">系统要求 <a class="header-anchor" href="#系统要求" aria-label="Permalink to &quot;系统要求&quot;">​</a></h2><ul><li>Windows 10 2004 及以上版本，或 Windows 11，64 位。</li><li>Microsoft Edge WebView2 运行时。几乎所有 Windows 10 和 11 电脑都已预装。如果 MeetCue 提示 <a href="/meetcue/zh/troubleshooting/error-codes#mc-sys-001">MC-SYS-001</a>，请从微软官网安装 Evergreen 版运行时。</li><li>一个语音识别供应商的 API 密钥，和一个大模型供应商的 API 密钥。参见<a href="/meetcue/zh/guide/providers">供应商配置</a>。</li></ul><div class="info custom-block"><p class="custom-block-title">macOS 与 Linux</p><p>MeetCue 可以在 macOS 和 Linux 上编译运行，但当前版本只在 Windows 上支持音频采集。</p></div><h2 id="用-scoop-安装" tabindex="-1">用 Scoop 安装 <a class="header-anchor" href="#用-scoop-安装" aria-label="Permalink to &quot;用 Scoop 安装&quot;">​</a></h2><ol><li><p>如果还没有安装 Scoop，打开 PowerShell 并运行：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Set-ExecutionPolicy</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ExecutionPolicy RemoteSigned </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Scope CurrentUser</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">irm get.scoop.sh </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> iex</span></span></code></pre></div></li><li><p>添加 MeetCue 的 bucket：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">scoop bucket add meetcue https:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">//</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">github.com</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Amazingkenneth</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">meetcue</span></span></code></pre></div></li><li><p>安装 MeetCue：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">scoop install meetcue</span></span></code></pre></div></li><li><p>从开始菜单启动 <strong>MeetCue</strong>。首次运行会打开设置向导，请继续阅读<a href="/meetcue/zh/setup">首次设置</a>。</p></li></ol><h2 id="升级" tabindex="-1">升级 <a class="header-anchor" href="#升级" aria-label="Permalink to &quot;升级&quot;">​</a></h2><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">scoop update meetcue</span></span></code></pre></div><p>设置、延迟探测历史和练习记录保存在 Scoop 的 <code>persist</code> 目录中，API 密钥保存在 Windows 凭据管理器中，因此升级后都会保留。</p><h2 id="卸载" tabindex="-1">卸载 <a class="header-anchor" href="#卸载" aria-label="Permalink to &quot;卸载&quot;">​</a></h2><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">scoop uninstall meetcue</span></span></code></pre></div><p>如果要同时删除设置，加上 <code>--purge</code>。API 密钥保留在 Windows 凭据管理器中名为 <code>MeetCue</code> 的条目里，如有需要请在那里删除。</p><h2 id="遇到问题" tabindex="-1">遇到问题 <a class="header-anchor" href="#遇到问题" aria-label="Permalink to &quot;遇到问题&quot;">​</a></h2><p>请参阅<a href="/meetcue/zh/troubleshooting/install">安装与升级排错</a>。</p>`,15)])])}const u=s(l,[["render",o]]);export{k as __pageData,u as default};
